import test from'node:test';import assert from'node:assert/strict';import{create,initial,assess,simulate,edges}from'./engine.js';
test('synchronous choices use neighbours before the round and respect switching costs',()=>{const s=create(),a=initial(s),d=assess(s,a);assert.equal(d[2].share,.4);assert.ok(Math.abs(d[2].gain-.4)<1e-9);assert.equal(d[2].next,false);s.switching=0;assert.equal(assess(s,a)[2].next,true);assert.equal(a[2],false);});
// Fixed personal differences can let one early follower trigger a cascade; this fixture stays below that threshold.
test('critical mass, standalone benefit and compatibility can each change the trajectory',()=>{const s=create(),base=simulate(s);const pilot=simulate({...s,seeds:[0,1,2]}),solo=simulate({...s,benefit:12}),compatible=simulate({...s,compatibility:1});assert.ok(pilot.final.filter(Boolean).length>base.final.filter(Boolean).length);assert.equal(solo.final.filter(Boolean).length,12);assert.equal(compatible.final.filter(Boolean).length,12);assert.deepEqual(simulate(s),base);});
test('pilot commitment is explicit and bridges change real neighbour sets',()=>{const s={...create(),benefit:0,seeds:[0],hold:false};assert.equal(simulate(s).final[0],false);assert.equal(simulate({...s,hold:true}).final[0],true);assert.equal(edges(s).length,30);assert.equal(edges({...s,bridge:true}).length,32);assert.equal(assess({...s,bridge:true},initial(s))[2].share,1/6);});
